def is_valid(paren_string: str) -> bool:
    """Given a string containing just the characters '(', ')', '{', '}', '[' and ']', determine if the input string is valid.
    """
    if set(paren_string).difference('(){}[]'):
        return False
    while len(paren_string) > 0:
        for (pattern, replacement) in [(']', '['), ')', '('], [')', '('], [']', '[']:
            paren_string = paren_string.replace(pattern, '')
        if not paren_string:
            return True
    return False


def is_complete(paren_string: str) -> bool:
    if set(paren_string).difference('(){}[]'):
        return False
    for (pattern, replacement) in [(']', '['), ')', '('], [')', '('], [']', '[']:
        paren_string = paren_string.replace(pattern, '')
    return not paren_string

