def is_well_formed(paren_string: str):
    """ Check if the passed string is well formed. E.g. (()())() is well formed while (((()))( is not.

    >>> is_well_formed('(()())()')
    True
    >>> is_well_formed('((()))( ')
    False
    """
    parens = ["(", ")"]
    depth = 0
    for char in paren_string:
        if char not in parens:
            raise ValueError("Invalid character in string")
        elif char == "(":
            depth += 1
        else:
            depth -= 1
        if depth < 0:
            raise ValueError("Left parentheses are not closed")

    return depth == 0


