def round_to_next5(num: float) -> float:
    """Round a positive number to the next multiple of 5.
    Round zero to 0, round negative numbers down to the closest multiple of 5.
    >>> round_to_next5(1.5)
    5
    >>> round_to_next5(14)
    15
    """
    if (round(num, 1) - num) < 0.5:
        return round(num, 1)
    else:
        return round(num - float(truncate(num)), 1) + 0.5


